export const addAlbum = (album) => {

    return{
        type: "ADD_ALBUM",
        payload: {
            id: Date.now(),
            album,
        }
    }
}


export const removeAlbum = (id) => {

    return {
        type: "REMOVE_ALBUM",
        payload: id,
    }
}
